package backend;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.index.Indexed;
import org.springframework.data.mongodb.core.mapping.Document;

/**
 * Invoice document stored in the MongoDB collection "invoices".
 *
 * invoiceNumber is a unique business key generated by {@link InvoiceService}.
 * The client and (optional) project are stored as stable id references; display
 * names are resolved at read time.
 *
 * The stored {@code status} only records the issue state (DRAFT or SENT).
 * Payment and overdue states (PARTIALLY_PAID, PAID, OVERDUE) are derived from
 * the recorded payments and the due date so they can never fall out of sync.
 *
 * Money is stored as {@link BigDecimal}; all rounding is applied centrally by
 * {@link InvoiceService} with HALF_UP at scale 2.
 */
@Document(collection = "invoices")
public class Invoice {

    @Id
    private String id;

    @Indexed(unique = true)
    private String invoiceNumber;

    /** Client id the invoice is billed to. */
    private String clientId;

    /** Project id the invoice relates to (may be null). */
    private String projectId;

    private LocalDate issueDate;
    private LocalDate dueDate;

    /** DRAFT | SENT — the issue state; other states are derived. */
    private String status;

    private List<InvoiceLineItem> lineItems = new ArrayList<>();

    /** Tax percentage applied to the discounted subtotal (e.g. 18 = 18%). */
    private BigDecimal taxRate;

    /** Absolute discount applied to the subtotal. */
    private BigDecimal discount;

    private String notes;

    /** Email of the authenticated user who created the invoice. */
    private String createdBy;

    private Instant createdAt;
    private Instant updatedAt;

    public Invoice() {
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getInvoiceNumber() {
        return invoiceNumber;
    }

    public void setInvoiceNumber(String invoiceNumber) {
        this.invoiceNumber = invoiceNumber;
    }

    public String getClientId() {
        return clientId;
    }

    public void setClientId(String clientId) {
        this.clientId = clientId;
    }

    public String getProjectId() {
        return projectId;
    }

    public void setProjectId(String projectId) {
        this.projectId = projectId;
    }

    public LocalDate getIssueDate() {
        return issueDate;
    }

    public void setIssueDate(LocalDate issueDate) {
        this.issueDate = issueDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    public void setDueDate(LocalDate dueDate) {
        this.dueDate = dueDate;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public List<InvoiceLineItem> getLineItems() {
        return lineItems;
    }

    public void setLineItems(List<InvoiceLineItem> lineItems) {
        this.lineItems = lineItems == null
                ? new ArrayList<>()
                : new ArrayList<>(lineItems);
    }

    public BigDecimal getTaxRate() {
        return taxRate;
    }

    public void setTaxRate(BigDecimal taxRate) {
        this.taxRate = taxRate;
    }

    public BigDecimal getDiscount() {
        return discount;
    }

    public void setDiscount(BigDecimal discount) {
        this.discount = discount;
    }

    public String getNotes() {
        return notes;
    }

    public void setNotes(String notes) {
        this.notes = notes;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public void setCreatedBy(String createdBy) {
        this.createdBy = createdBy;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}
